-- 15: question texts for the autoresearch results dashboard (service role only; rebuilt from autoresearch/questions.json)
create table if not exists llm.eval_questions (id text primary key, section text not null, split text not null, kind text, question text not null);
alter table llm.eval_questions enable row level security;
on conflict (id) do update set section = excluded.section, split = excluded.split, kind = excluded.kind, question = excluded.question;
